<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Payment extends Model { protected $fillable=['invoice_id','customer_id','reference','amount','currency','method','gateway','transaction_id','status','receipt_number','proof_path','staff_notes','paid_at','refunded_at']; protected $casts=['amount'=>'decimal:2','paid_at'=>'datetime','refunded_at'=>'datetime']; protected static function booted(){static::creating(function(self $m){$m->reference??='PAY-'.now()->format('YmdHis').'-'.str(str()->random(5))->upper();}); static::saved(function(self $m){if($m->invoice){$m->invoice->load('items','payments');$m->invoice->recalculate();$m->invoice->saveQuietly();} if(auth()->check()){AuditLog::create(['user_id'=>auth()->id(),'action'=>'payment.updated','auditable_type'=>self::class,'auditable_id'=>$m->id,'ip_address'=>request()->ip()]);}});} public function invoice(){return $this->belongsTo(Invoice::class);} public function customer(){return $this->belongsTo(Customer::class);} }
